ns(uint256){ return calculateTrade(drugs,marketDrugs,this.balance); } function calculateDrugBuy(uint256 eth,uint256 contractBalance) public view returns(uint256){ return calculateTrade(eth,contractBalance,marketDrugs); } function calculateDrugBuySimple(uint256 eth) public view returns(uint256){ return calculateDrugBuy(eth,this.balance); } function devFee(uint256 amount) public view returns(uint256){ return SafeMath.div(SafeMath.mul(amount,4),100); } function seedMarket(uint256 drugs) public payable{ require(marketDrugs==0); initialized=true; marketDrugs=drugs; } function getFreeKilo() public{ require(initialized); require(Kilos[msg.sender]==0); lastCollect[msg.sender]=now; Kilos[msg.sender]=STARTING_KILOS; } function getBalance() public view returns(uint256){ return this.balance; } function getMyKilo() public view returns(uint256){ return Kilos[msg.sender]; } function getMyDrugs() public view returns(uint256){ return SafeMath.add(claimedDrugs[msg.sender],getDrugsSinceLastCollect(msg.sender)); } function getDrugsSinceLastCollect(address adr) public view returns(uint256){ uint256 secondsPassed=min(DRUGS_TO_PRODUCE_1KILO,SafeMath.sub(now,lastCollect[adr])); return SafeMath.mul(secondsPassed,Kilos[adr]); } function min(uint256 a, uint256 b) private pure returns (uint256) { return a < b ? a : b; } } library SafeMath { function mul(uint256 a, uint256 b) internal pure returns (uint256) { if (a == 0) { return 0; } uint256 c = a * b; assert(c / a == b); return c; } function div(uint256 a, uint256 b) internal pure returns (uint256) { uint256 c = a / b; return c; } function sub(uint256 a, uint256 b) internal pure returns (uint256) { assert(b <= a); return a - b; } function add(uint256 a, uint256 b) internal pure returns (uint256) { uint256 c = a + b; assert(c >= a); return c; } }

